package kr.ioniq5.usbcp;public final class ManualCarplay {public static final int READY=0,ACCEPTED=1,CONNECTED=2,BUSY=3,POWER_OFF=4,DISABLED=5,AP_UNAVAILABLE=6,PHONE_REQUIRED=7,NOT_APPLE=8,TIMED_OUT=9,FAILED=10;public static final int CURRENT_HFP=1,ACTIVE_CP=2,ACTIVE_TARGET=4,PENDING_TARGET=8;public static class Result {public int status,flags;public Result(int s,int f){status=s;flags=f;}}public static volatile int queries,retries,mainQueries;public static volatile boolean fail;public static volatile int queryStatus=READY,queryFlags=CURRENT_HFP;public static volatile int retryStatus=ACCEPTED,retryFlags=PENDING_TARGET;public static Result query(byte[] a)throws java.io.IOException {queries++;if(android.os.Looper.myLooper()==android.os.Looper.getMainLooper())mainQueries++;if(fail)throw new java.io.IOException("PRIVATE-ADDRESS");return new Result(queryStatus,queryFlags);}public static Result retry(byte[] a)throws java.io.IOException {retries++;if(fail)throw new java.io.IOException("PRIVATE-ADDRESS");return new Result(retryStatus,retryFlags);}public static void reset(){queries=retries=mainQueries=0;fail=false;queryStatus=READY;queryFlags=CURRENT_HFP;retryStatus=ACCEPTED;retryFlags=PENDING_TARGET;}}
